INSERT INTO `tb_content` (`fidsys`, `fname`, `fdesc`, `fdescen`, `fheader`, `fheaderen`, `fcontent`, `fcontenten`, `fbgcolor`, `fcolor`, `fstatusrow`, `fheight`, `flastuser`, `fseotitle`, `fmetakey`, `fmetadesc`, `fgroup`, `ftglentry`, `flastupdate`) VALUES
(235, 'beranda1', 'Panduan Umum / Admin', '', 'Panduan Umum / Admin', '', '<h1>PT. AMINAH</h1>\r\n<h1>Jl. Raya Wiguna Timur 48A SBY</h1>\r\n<p>TLP. 031-87854771</p>\r\n<p>Email aminah_a54@yahoo.com</p>\r\n<p>Â </p>\r\n<p>NOMOR Hp dan. BAGIAN-BAGIAN PELAYANAN</p>\r\n<p>(Hanya melayani WA)</p>\r\n<p>Â </p>\r\n<p>1. BAGIAN PROGRAM APLIKASI/AMH/INTERN</p>\r\n<p>Mbak NINIK = 087704626863</p>\r\n<p>Â </p>\r\n<p>2. BAGIAN ADMINISTRASI KEUANGAN</p>\r\n<p>Mbak LINA = 087704626862</p>\r\n<p>Â </p>\r\n<p>3. BAGIAN BERKAS</p>\r\n<p>Mas Amir = 087704626864</p>\r\n<p>Â </p>\r\n<p>4. BAGIAN LOGISTIK/PENGURUSAN PASPORT/SUNTIK MININGITIS</p>\r\n<p>Mas AMIR = 087855165559</p>', '', '', '', '1', 800, 'ADMIN_2', NULL, NULL, NULL, 'home', NULL, NULL),
(236, 'beranda2', 'Panduan Korwil / Sub Korwil', '', 'Panduan Korwil / Sub Korwil', '', '<div class=\"services-project default-size\">\r\n<div class=\"services-gal\"><strong><span style=\"font-size: large;\">Tata Cara Korwil / Sub Korwil</span></strong></div>\r\n</div>\r\n<div class=\"services-gal\">\r\n<div class=\"services-gal\"><ol>\r\n<li>Mentaati peraturan yg dikeluarkan PT. AMINAH yang berlaku.</li>\r\n<li>Menghormati atasan yang lebih tinggi.</li>\r\n<li>Menjaga nama baik PT. AMINAH dg merk dagang AMINAH TOUR.</li>\r\n<li>Dana yang telah masuk sebagai Korwil/Sub Korwil tidak dapat diambil kembali dengan cara apapun, kecuali dialihkan hanya untuk tahun pertama.</li>\r\n<li>Mengikuti Pelatihan/gathering khusus Sub Korwil atau Korwil</li>\r\n<li>Tidak menjalankan usaha sejenis (travel tour,umroh/haji khusus).</li>\r\n<li>Menerima dan mendaftarkan calon jamaah sesuai jenis/program tahun berjalan.</li>\r\n<li>Tidak menerima pembayaran CALON JAMAAH, kecuali dibayarkan atau ditransfer ke rek. perusahaan <br /><br />PT. AMINAH<br />BANK MANDIRI<br />No. Rek. 14200.1366.2985<br />BANK BNI<br />No. Rek. 8888881455<br /><br /></li>\r\n<li>Pencairan Saldo, minimal Rp. 100.000,-</li>\r\n<li>Biaya administrasi transfer antar Bank ditanggung Pebisnis.</li>\r\n<li>Transfer antar Pebisnis minimal Rp. 5.000,-</li>\r\n<li>Tidak menggunakan nama merk dagang AMINAH TOUR tanpa seijin PT. AMINAH.</li>\r\n<li>Tidak melakukan up harga paket/program yang dikeluarkan PT. AMINAH.</li>\r\n<li>Jadwal dan Harga sewaktu-waktu dapat berubah tanpa pemberitahuan dan menyesuaikan situasi dan kondisi.</li>\r\n<li>Melaporkan kasus-kasus yang terjadi dilapangan yang melibatkan nama PT. AMINAH.</li>\r\n<li>Setuju dan Menjelaskan, bahwa dana yang telah masuk tidak bisa diambil kembali hanya boleh dialihkan (setelah dipotong biaya yang dikeluarkan PT. AMINAH)</li>\r\n<li>Setuju dan Menjelaskan, bahwa Calon Jamaah Umroh/Calon Wisatawan WAJIB mengisi FORMULIR PENDAFTARANÂ  yang telah disiapkan PT. AMINAH</li>\r\n<li>Apabila saya melanggar hal-hal yang dinyatakan dalam Pakta Integritas ini, saya bersedia menerima sanksi administrasi (Saldo hangus dan dikeluarkan), digugat secara perdata dan atau dilaporkan secara pidana.</li>\r\n</ol></div>\r\n</div>\r\n<div class=\"services-project\">\r\n<div class=\"services-gal\"></div>\r\n</div>', '', '', '', '1', 800, 'ADMIN_2', NULL, NULL, NULL, 'home', NULL, NULL),
(251, 'beranda3', 'Panduan Pebisnis', '', 'TATA CARA & KETENTUAN', '', '<p>Â </p>\r\n<p>TATA CARA &amp; KETENTUAN</p>\r\n<p>PENGGUNA APLIKASI/PEBISNIS</p>\r\n<p>1. APLIKASI Berbasis Website menggunakan \"Login &amp; Pasword\"</p>\r\n<p>2Â  PENGGUNA APLIKASI/PEBISNIS harus mempunyai \"Login &amp; Pasword\" yang selanjutnya disebut Pemilik</p>\r\n<p>3Â  \"Login &amp; Pasword\" bersifat privasi dan rahasia bagi Pemilik.</p>\r\n<p>4. Pemilik \"Login &amp; Pasword\" bertanggungjawab atas segala bentuk transaksi.</p>\r\n<p>5. Penyalahgunaan \"Login &amp; Pasword\", PTÂ  AMINAH tidak bertanggungjawab dan dibebaskan yang</p>\r\n<p>terkaitm dengan hukum.</p>\r\n<p>6Â  Segala bentuk transaksi, harus sesuai dengan tatacara &amp; ketentuan yang berlaku.</p>\r\n<p>7. Segala bentuk transaksi, harus menggunakan rekening PT. AMINAH.</p>\r\n<p>PT. AMINAH<br /> BANK MANDIRI<br /> No. Rek. 14200.1366.2985</p>\r\n<p><br /> PT. AMINAH<br /> BANK BNI<br /> No. Rek. 8888881455</p>\r\n<p>Â </p>\r\n<p>TATA CARA &amp; KETENTUAN</p>\r\n<p>PENDAFTARAN</p>\r\n<p>TOUR/UMROH/HAJI</p>\r\n<p>1. Mengisi Formulir Pendaftaran.</p>\r\n<p>2. Menyetorkan Pasport yang masuh berlaku 7 bulan saat keberangkatan dengan Nama 3 kata.</p>\r\n<p>3. Menyetorkan buku vaksin &amp; influensa Asli yang dikeluarkan KKP untuk Umroh.</p>\r\n<p>4. Surat mahrom bagi perempuan umur &lt;45 tahun, umroh sendiri tanpa suami/Sausara laki2/Bapak</p>\r\n<p>Kandung</p>\r\n<p>5. Foto berwarna background putih &amp; tampak wajah 80%, 3x4 dan 4x6 masing2 4 lembar</p>\r\n<p>6. Surat nikah asli bagi suami istri umurÂ  &lt; 45 tahun</p>\r\n<p>7. Foto copy akte lahir bagi anak umur &lt; 17 tahun</p>\r\n<p>8. Foto copy akte lahir bagi perempuan umur &lt; 45 tahun yang berangkat bersama orang tua.</p>\r\n<p>9. Khusus program TPU (Tabungan Percepatan Umroh) dan TPHF (Tabungan Percepatan Haji Furoda),</p>\r\n<p>teknik pembayaran dengan 3 tahap</p>\r\n<p>aÂ  Tahap-1 = membayar administrasi program (TPU = 1.500.000,Â  Â TPHF = 7.500.000)</p>\r\n<p>b. Tahap-2 = Membayar booking seat keberangkatan (TPU = 6.000.000, TPHF = $8000)</p>\r\n<p>c. Tahap-3 = PELUNASAN</p>\r\n<p>PEMBAYARAN MENGGUNAKAN TEKNIK AUTODEBET.</p>\r\n<p>Biaya belum termasuk</p>\r\n<p>1. Pengurusan Pasport dan tambah kata nama.</p>\r\n<p>2. Dokumen tambahan untuk perempuan umur &lt; 45 tahun umroh sendiri tanpa suami/saudara</p>\r\n<p>laki2/bapak kandung</p>\r\n<p>3. Pengeluaran pribadi mis. Loundry, telepon hotel/ pribadi, kelebihan bagasi max 20 kg/sesuai aturan</p>\r\n<p>maskapai.</p>\r\n<p>4. Biaya kesehatan &amp; vaksin manangitis.</p>\r\n<p>5. Biaya REGULASI , jika ada seperti kenaikkan PPNB Saudi, vaksin covid 19 (PCR), Karantina dan biaya</p>\r\n<p>tiket akibat social distancing.</p>\r\n<p>6. Pengurusan Visa diluar Saudi Arabia dan Asuransi</p>\r\n<p>Â </p>\r\n<p>PEMBATALAN</p>\r\n<p>Pembatalan yang dilakukan satu bulan sebelum pemberangkatan, dikenakan pemotongan 75% dari dana</p>\r\n<p>yang masuk dan kurang dari satu bulanÂ  sebelum pemberangkatan dikenakan biaya full kecuali dialihkan</p>\r\n<p>dengan mengganti biaya pergantian Nama (Visa, Tiket, Asuransi).</p>\r\n<p>Tidak menerima pembayaran CALON JAMAAH, kecuali dibayarkan atau ditransfer ke rek. PT. AMINAH</p>\r\n<ol>\r\n<li>PT. AMINAH<br />BANK MANDIRI<br />No. Rek. 14200.1366.2985</li>\r\n<li>PT. AMINAH<br />BANK BNI<br />No. Rek. 8888881455</li>\r\n<br />&lt;&lt;&lt;&lt;&lt;&lt;&lt;</ol>', '', '', '', '1', 800, 'ADMIN_2', NULL, NULL, NULL, 'home', NULL, NULL),
