INSERT INTO `tb_recomm` (`fidsys`, `fname`, `fdesc`, `fcontent`, `fstatusrow`, `fdefault`, `ftglentry`, `flastupdate`) VALUES
(1, 'recom1', 'Template Imigrasi Surabaya', '<div class=\"panel-body\" id=\"bodypanel\">\r\n<div align=\"center\" style=\"font-weight: bold;\" id=\"content\">\r\n<h4><strong>Rekomendasi Pengurusan Paspor</strong></h4>\r\n</div>\r\n<br />\r\n<p>Surabaya, {TGL} {BLN} {THN}<br /> Kepada Yth. <br /> Kepala Kantor Imigrasi <br /> Surabaya <br /> Perihal : Permohonan Pembuatan / Perpanjangan Paspor.</p>\r\n<p><br /> Dengan Hormat, <br /> Sehubungan dengan adanya rencana perjalanan Umroh kami melalui PT Aminah Tour &amp; Travel, bersama ini kami mohon agar dapat dibuatkan paspor baru/perpanjang paspor kami:</p>\r\n<p></p>\r\n<table width=\"700\" border=\"0\" cellpadding=\"3\" cellspacing=\"0\" class=\"add-on\">\r\n<tbody>\r\n<tr style=\"height: 10px;\">\r\n<td width=\"171\"><span class=\"col-lg-2\">Nama</span></td>\r\n<td width=\"8\">:</td>\r\n<td width=\"504\">{NAMA}</td>\r\n</tr>\r\n<tr style=\"height: 10px;\">\r\n<td valign=\"top\">Alamat</td>\r\n<td valign=\"top\">:</td>\r\n<td valign=\"top\">{ALAMAT}</td>\r\n</tr>\r\n<tr style=\"height: 10px;\">\r\n<td nowrap=\"nowrap\">Nomor KTP</td>\r\n<td>:</td>\r\n<td>{NOKTP}</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Hormat Kami,</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>PT Aminah Tour and Travel</p>\r\n</div>', '1', '0', '2019-08-07 09:46:54', NULL),
(2, 'recom2', 'Template Imigrasi Mojokerto', '<div class=\"panel-body\" id=\"bodypanel\">\r\n<div align=\"center\" style=\"font-weight: bold;\" id=\"content\">\r\n<h4><strong>Rekomendasi Pengurusan Paspor</strong></h4>\r\n</div>\r\n<br />\r\n<p>Surabaya, {TGL} {BLN} {THN}<br /> Kepada Yth. <br /> Kepala Kantor Imigrasi <br />Mojokerto<br /> Perihal : Permohonan Pembuatan / Perpanjangan Paspor.</p>\r\n<p><br /> Dengan Hormat, <br /> Sehubungan dengan adanya rencana perjalanan Umroh kami melalui PT Aminah Tour &amp; Travel, bersama ini kami mohon agar dapat dibuatkan paspor baru/perpanjang paspor kami:</p>\r\n<p></p>\r\n<table width=\"700\" border=\"0\" cellpadding=\"3\" cellspacing=\"0\" class=\"add-on\">\r\n<tbody>\r\n<tr style=\"height: 10px;\">\r\n<td width=\"171\"><span class=\"col-lg-2\">Nama</span></td>\r\n<td width=\"8\">:</td>\r\n<td width=\"504\">{NAMA}</td>\r\n</tr>\r\n<tr style=\"height: 10px;\">\r\n<td valign=\"top\">Alamat</td>\r\n<td valign=\"top\">:</td>\r\n<td valign=\"top\">{ALAMAT}</td>\r\n</tr>\r\n<tr style=\"height: 10px;\">\r\n<td nowrap=\"nowrap\">Nomor KTP</td>\r\n<td>:</td>\r\n<td>{NOKTP}</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>Hormat Kami,</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>PT Aminah Tour and Travel</p>\r\n</div>', '1', '1', '2019-08-07 09:46:54', NULL);
